citation(eu_dir_2014_24_art_27, [label - 'Directive 2014/24/EU, Article 27 (Open procedure)', ref - 'http://publications.europa.eu/resource/celex/02014L0024-20260101.ENG.fmx4', verbatim - 'The minimum time limit for the receipt of tenders shall be 35 days from the date on which the contract notice was sent.', units - ['02014L0024-20260101#parag_027.001', '02014L0024-20260101#parag_027.002', '02014L0024-20260101#point_027.002_a', '02014L0024-20260101#point_027.002_b', '02014L0024-20260101#parag_027.003', '02014L0024-20260101#parag_027.004']]).
citation(eu_dir_2014_24_art_28, [label - 'Directive 2014/24/EU, Article 28 (Restricted procedure)', ref - 'http://publications.europa.eu/resource/celex/02014L0024-20260101.ENG.fmx4', verbatim - 'The minimum time limit for receipt of requests to participate shall be 30 days from the date on which the contract notice or, where a prior information notice is used as a means of calling for competition, the invitation to confirm interest was sent.', units - ['02014L0024-20260101#parag_028.001', '02014L0024-20260101#parag_028.002', '02014L0024-20260101#parag_028.003', '02014L0024-20260101#point_028.003_a', '02014L0024-20260101#point_028.003_b', '02014L0024-20260101#parag_028.005', '02014L0024-20260101#parag_028.006', '02014L0024-20260101#point_028.006_a', '02014L0024-20260101#point_028.006_b']]).
citation(eu_dir_2014_24_art_29, [label - 'Directive 2014/24/EU, Article 29 (Competitive procedure with negotiation)', ref - 'http://publications.europa.eu/resource/celex/02014L0024-20260101.ENG.fmx4', verbatim - 'The minimum time limit for receipt of requests to participate shall be 30 days from the date on which the contract notice or, where a prior information notice is used as a means of calling for competition, the invitation to confirm interest was sent. The minimum time limit for the receipt of initial tenders shall be 30 days from the date on which the invitation was sent. Article 28(3) to (6) shall apply.', units - ['02014L0024-20260101#parag_029.001']]).
citation(eu_dir_2014_24_art_30, [label - 'Directive 2014/24/EU, Article 30 (Competitive dialogue)', ref - 'http://publications.europa.eu/resource/celex/02014L0024-20260101.ENG.fmx4', verbatim - 'The minimum time limit for receipt of requests to participate shall be 30 days from the date on which the contract notice was sent.', units - ['02014L0024-20260101#parag_030.001']]).
citation(eu_dir_2014_24_art_31, [label - 'Directive 2014/24/EU, Article 31 (Innovation partnership)', ref - 'http://publications.europa.eu/resource/celex/02014L0024-20260101.ENG.fmx4', verbatim - 'The minimum time limit for receipt of requests to participate shall be 30 days from the date on which the contract notice is sent.', units - ['02014L0024-20260101#parag_031.001']]).

